function getdata(t,e){fetch(t).then(t=>t.json()).then(t=>{$(".product-list-item").removeClass("active"),e.addClass("active"),$("#product-content").html(t.content),$("#loader").css("display","none")})}$(".product-list-item").on("click",function(t){t.preventDefault();let e=$(this),a=e.data("href");$("#loader").css("display","flex"),getdata(a,e)}),setTimeout(function(){if(window.location.hash.length>0){var t=window.location.hash.replace("#","");"ar"==window.language&&(t=decodeURIComponent(t));let e=$(document).find('.product-list-item[data-hash="'+t+'"]'),a=e.data("href");$("#loader").css("display","flex"),getdata(a,e)}});